package top.monitorglobal.tv;
import android.os.Handler;import android.os.Looper;import android.graphics.Bitmap;import com.google.zxing.*;import com.google.zxing.common.BitMatrix;import com.google.zxing.qrcode.QRCodeWriter;import com.google.zxing.qrcode.decoder.ErrorCorrectionLevel;import java.net.*;import java.util.*;import java.nio.file.Files;
import android.app.*;import android.content.*;import android.graphics.Color;import android.net.Uri;import android.os.Bundle;import android.widget.*;import java.io.*;import java.text.DateFormat;import org.json.*;
/** Owner-visible local report; nothing is uploaded automatically. */
public final class DiagnosticsActivity extends Activity {
 private TextView text;private File pending;private Button previousDownload;private LocalDiagnosticDownload download;private AlertDialog downloadDialog;private final Handler ui=new Handler(Looper.getMainLooper());private Runnable expired;
 public void onCreate(Bundle state){super.onCreate(state);LinearLayout content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(36,24,36,24);ScrollView scroll=new ScrollView(this);scroll.addView(content);setContentView(scroll);text=new TextView(this);text.setTextColor(Color.WHITE);text.setTextSize(18);content.addView(text);button(content,"Baixar diagnóstico pelo celular (QR Code)",()->startDownload(false));previousDownload=button(content,"Baixar diagnóstico anterior à atualização",()->startDownload(true));button(content,"Atualizar leitura salva",()->showReport());button(content,"Salvar diagnóstico em arquivo JSON",()->{try{pending=RuntimeDiagnostics.export(this);Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"monitor-global-tv-diagnostico.json");startActivityForResult(i,34);}catch(IOException|RuntimeException e){Toast.makeText(this,"Sem gerenciador de arquivos. Tente Compartilhar diagnóstico.",Toast.LENGTH_LONG).show();}});button(content,"Compartilhar diagnóstico",()->{try{RuntimeDiagnostics.export(this);Uri uri=Uri.parse("content://"+getPackageName()+".diagnostics/report");Intent i=new Intent(Intent.ACTION_SEND).setType("application/json").putExtra(Intent.EXTRA_STREAM,uri);i.setClipData(ClipData.newRawUri("Diagnóstico local",uri));i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(i,"Exportar diagnóstico local"));}catch(IOException|RuntimeException e){Toast.makeText(this,"Nenhum aplicativo de compartilhamento disponível neste aparelho.",Toast.LENGTH_LONG).show();}});showReport();}
 private Button button(LinearLayout row,String label,Runnable action){Button b=new Button(this);b.setText(label);b.setOnClickListener(v->action.run());row.addView(b);return b;}
 private void showReport(){JSONObject prior=RuntimeDiagnostics.readPrevious(this);JSONArray previous=prior.optJSONArray("samples");boolean hasPrevious=previous!=null&&previous.length()>0;previousDownload.setEnabled(hasPrevious);JSONObject r=RuntimeDiagnostics.read(this);JSONArray rows=r.optJSONArray("samples");if(rows==null||rows.length()==0){text.setText("DIAGNÓSTICO LOCAL\n\nAtive o monitoramento. A primeira leitura é feita em segundo plano; depois, uma por minuto. Nenhum dado é enviado automaticamente.\n\nVolte aqui para atualizar ou exportar a leitura salva.");return;}JSONObject last=rows.optJSONObject(rows.length()-1),frame=last.optJSONObject("banner");text.setText("DIAGNÓSTICO LOCAL · "+r.optString("device")+"\nAplicativo "+r.optString("version")+" · Android API "+r.optInt("sdk")+"\nÚltima leitura: "+DateFormat.getDateTimeInstance().format(new java.util.Date(last.optLong("at")))+"\nLeituras neste processo: "+r.optLong("sampleCount")+" · guardadas: "+rows.length()+"/"+RuntimeDiagnostics.MAX_SAMPLES+"\n\nMemória PSS do processo: "+(last.optBoolean("pssAvailable")?mb(last.optLong("pssKb")*1024):"indisponível nesta leitura")+"\nInicial: "+(r.optLong("baselinePssKb")>0?mb(r.optLong("baselinePssKb")*1024):"indisponível")+" · pico: "+(r.optLong("peakPssKb")>0?mb(r.optLong("peakPssKb")*1024):"indisponível")+"\nJava em uso: "+mb(last.optLong("javaUsedBytes"))+"\nAlocações nativas: "+mb(last.optLong("nativeAllocatedBytes"))+"\n\nDesenhos da tarja: "+(frame==null?0:frame.optLong("drawnFrames"))+"\nIntervalos maiores que 50 ms: "+(frame==null?0:frame.optLong("gapsOver50ms"))+"\nIntervalos maiores que 100 ms: "+(frame==null?0:frame.optLong("gapsOver100ms"))+"\n\nPSS, Java e nativa são medidas diferentes: não some os valores. Intervalos de desenho não são FPS nem medição completa da GPU. Coleta somente durante monitoramento, um registro por minuto, com retenção limitada; dados ficam neste aparelho. Use Baixar pelo celular para obter o JSON na mesma rede Wi-Fi. Salvar e Compartilhar são alternativas que dependem dos aplicativos da TV.");}
 private static InetAddress lanAddress()throws IOException{
  Enumeration<NetworkInterface> interfaces=NetworkInterface.getNetworkInterfaces();
  while(interfaces.hasMoreElements()){NetworkInterface net=interfaces.nextElement();if(!net.isUp()||net.isLoopback()||!(net.getName().startsWith("wlan")||net.getName().startsWith("eth")))continue;Enumeration<InetAddress> addresses=net.getInetAddresses();while(addresses.hasMoreElements()){InetAddress a=addresses.nextElement();if(a instanceof Inet4Address&&a.isSiteLocalAddress())return a;}}
  throw new IOException("Conecte a TV a uma rede Wi-Fi ou Ethernet local.");
 }
 private void startDownload(boolean previous){try{startDownload(previous,lanAddress());}catch(IOException|RuntimeException e){Toast.makeText(this,"Conecte a TV e o celular à mesma rede local e tente novamente.",Toast.LENGTH_LONG).show();}}
 void startDownload(boolean previous,InetAddress bindAddress){
  stopDownload();
  try{
   JSONObject report=previous?RuntimeDiagnostics.readPrevious(this):RuntimeDiagnostics.read(this);JSONArray samples=report.optJSONArray("samples");if(samples==null||samples.length()==0)throw new IOException("Ainda não há leituras nessa sessão.");
   File exported=RuntimeDiagnostics.export(this,previous);byte[] bytes=Files.readAllBytes(exported.toPath());download=new LocalDiagnosticDownload(bindAddress,bytes,previous,LocalDiagnosticDownload.DURATION_MS);
   String url=download.url();BitMatrix qr=new QRCodeWriter().encode(url,BarcodeFormat.QR_CODE,384,384,Collections.singletonMap(EncodeHintType.ERROR_CORRECTION,ErrorCorrectionLevel.M));int[] pixels=new int[384*384];for(int y=0;y<384;y++)for(int x=0;x<384;x++)pixels[y*384+x]=qr.get(x,y)?Color.BLACK:Color.WHITE;Bitmap bitmap=Bitmap.createBitmap(pixels,384,384,Bitmap.Config.ARGB_8888);
   LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.HORIZONTAL);body.setPadding(28,12,28,12);LinearLayout details=new LinearLayout(this);details.setOrientation(LinearLayout.VERTICAL);details.setPadding(20,0,0,0);
   TextView instructions=new TextView(this);instructions.setTextColor(Color.WHITE);instructions.setTextSize(17);instructions.setText("TV e celular na mesma rede; no celular, use Wi-Fi. Aponte a câmera do celular para o QR Code e abra o link para baixar o JSON.\n\n"+(previous?"Sessão anterior":"Sessão salva")+" · "+report.optString("version")+" · "+report.optLong("sampleCount")+" leituras.\nLink disponível por até 5 minutos. Mantenha esta tela aberta.");details.addView(instructions);
   ImageView image=new ImageView(this);image.setImageBitmap(bitmap);int side=(int)(220*getResources().getDisplayMetrics().density);LinearLayout.LayoutParams size=new LinearLayout.LayoutParams(side,side);size.gravity=android.view.Gravity.CENTER;body.addView(image,size);body.addView(details,new LinearLayout.LayoutParams(0,LinearLayout.LayoutParams.WRAP_CONTENT,1f));
   TextView address=new TextView(this);address.setTextColor(Color.WHITE);address.setTextSize(15);address.setText(url);details.addView(address);
   ScrollView scroll=new ScrollView(this);scroll.addView(body);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(previous?"Baixar diagnóstico anterior":"Baixar diagnóstico pelo celular").setView(scroll).setPositiveButton("Fechar",(d,w)->{}).create();downloadDialog=dialog;
   dialog.setOnDismissListener(d->{image.setImageDrawable(null);if(downloadDialog==dialog){downloadDialog=null;stopDownload();}});dialog.show();
   expired=()->{if(download!=null)download.close();instructions.setText("O link expirou. Feche esta janela e gere outro QR Code. Os diagnósticos continuam salvos na TV.");image.setImageDrawable(null);address.setText("");};ui.postDelayed(expired,LocalDiagnosticDownload.DURATION_MS);
  }catch(IOException|WriterException|RuntimeException e){stopDownload();Toast.makeText(this,e instanceof IOException?e.getMessage():"Não foi possível abrir o download local. Tente novamente.",Toast.LENGTH_LONG).show();}
 }
 private void stopDownload(){if(expired!=null){ui.removeCallbacks(expired);expired=null;}if(download!=null){download.close();download=null;}AlertDialog old=downloadDialog;downloadDialog=null;if(old!=null)old.dismiss();}
 @Override protected void onStop(){stopDownload();super.onStop();}
 private String mb(long bytes){return String.format(java.util.Locale.forLanguageTag("pt-BR"),"%.1f MiB",bytes/1048576.0);}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=34||result!=RESULT_OK||data==null||data.getData()==null||pending==null)return;try(InputStream in=new FileInputStream(pending);OutputStream out=getContentResolver().openOutputStream(data.getData())){if(out==null)throw new IOException("Destino indisponível");byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);Toast.makeText(this,"Diagnóstico salvo.",Toast.LENGTH_LONG).show();}catch(IOException|RuntimeException e){Toast.makeText(this,"Não foi possível salvar.",Toast.LENGTH_LONG).show();}finally{pending=null;}}
}
